export const NEIGHBORHOODS_BY_DISTRICT_ID = ALL_ISTANBUL_NEIGHBORHOODS.reduce((acc, n) => {
  if (!acc[n.districtId]) {
    acc[n.districtId] = [];
  }
  acc[n.districtId].push(n);
  return acc;
}, {});

export const NEIGHBORHOODS_BY_ID = ALL_ISTANBUL_NEIGHBORHOODS.reduce((acc, n) => {
  acc[n.id] = n;
  return acc;
}, {});

export function getDistrictNeighborhoods(districtId) {
  if (!districtId) return [];
  return NEIGHBORHOODS_BY_DISTRICT_ID[districtId] || [];
}

export function getNeighborhoodById(id) {
  if (!id) return null;
  return NEIGHBORHOODS_BY_ID[id] || null;
}

export function getNeighborhoodBySlug(districtId, slug) {
  if (!districtId || !slug) return null;
  const list = NEIGHBORHOODS_BY_DISTRICT_ID[districtId] || [];
  return list.find(n => n.slug === slug || n.id === slug) || null;
}
